-- Store the reviewed manual Malay and Tamil quiz translations in the same question bank
-- table as Thai, English and Chinese. Existing localized rows and attempts are untouched.
alter table public.question_localizations
  drop constraint question_localizations_language_check;
alter table public.question_localizations
  add constraint question_localizations_language_check
  check (language in ('th', 'en', 'zh', 'ms', 'ta'));

-- Match the English source exactly to avoid attaching a starter translation to an
-- owner-edited question. Owners can translate those skipped questions in the editor.
