  as s(question_key text, language text, source_prompt text, source_options jsonb,
       source_explanation text, prompt text, options jsonb, explanation text)
)
insert into public.question_localizations
  (question_id, language, prompt, options, correct_key, explanation, tts_enabled)
select q.id, t.language, t.prompt, t.options, q.correct_option_key, t.explanation, false
from translations t
join public.questions q on q.question_key = t.question_key
join public.question_localizations en on en.question_id = q.id and en.language = 'en'
where en.prompt = t.source_prompt
  and en.options = t.source_options
  and en.explanation is not distinct from t.source_explanation
  and q.question_key like 'mcq-v2-%'
on conflict (question_id, language) do nothing;
